    DoorB : BOOL;
END_VAR

IF OpenA_Cmd THEN
    DoorA := TRUE;
ELSE
    DoorA := FALSE;
END_IF;

IF OpenB_Cmd AND NOT DoorA THEN
    DoorB := TRUE;
ELSE
    DoorB := FALSE;
END_IF;

