            State := 4;
        END_IF;

    4: -- Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE

IF NOT EStop THEN
    State := 0;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_LOW : INT := 5;
    LVL_HIGH : INT := 80;
    TEMP_SET : INT := 100;
    LIQ_MIN : INT := 10;
    PT_REACT : INT := 3;
END_VAR
VAR
    State : INT;
END_VAR
VAR
    T1 : TON;
END_VAR

T1(IN := TRUE, PT := T#1s);

CASE State OF
    0: -- Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: -- Fill
        IF NOT EStop OR Level >= LVL_HIGH OR Level < LIQ_MIN THEN
            State := 0;
        END_IF;
        FillValve := Level < LVL_HIGH AND EStop AND Level >= LIQ_MIN;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

    2: -- Heat
        IF NOT EStop OR Temp >= TEMP_SET OR Level < LIQ_MIN THEN
            State := 3;
        END_IF;
        FillValve := FALSE;
        Heater := EStop AND Level >= LIQ_MIN;
        Agitator := EStop AND Level >= LIQ_MIN;
        DrainValve := FALSE;

    3: -- React
        IF NOT EStop OR T1.T >= PT_REACT OR Level < LIQ_MIN THEN
            State := 4;
        END_IF;
        FillValve := FALSE;
        Heater := EStop AND Level >= LIQ_MIN;
        Agitator := EStop AND Level >= LIQ_MIN;
        DrainValve := FALSE;

    4: -- Drain
        IF NOT EStop OR Level <= LVL_LOW THEN
            State := 0;
        END_IF;
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := Level > LVL_LOW AND EStop;

END_CASE;

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

