        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
        IF EStop OR StopPB OR State >= 2 THEN
            State := 0;
        ELSIF NOT EStop AND State = 1 AND TimeElapsed >= PT_STAR THEN
            State := 2;
        END_IF;

    2:
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
        IF EStop OR StopPB THEN
            State := 0;
        END_IF;

END_CASE

END_PROGRAM

