    Valve : BOOL;
END_VAR
VAR CONSTANT
    LOW : INT := 10;
    HIGH : INT := 90;
END_VAR
VAR
    State : INT;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF StartCycle AND Level < HIGH THEN
    State := 1;
ELSIF Level >= HIGH THEN
    State := 2;
ELSIF Level <= LOW THEN
    State := 0;
END_IF;

CASE State OF
    0:  // Idle
        Pump := FALSE;
        Valve := FALSE;
    1:  // Filling
        Pump := TRUE;
        Valve := FALSE;
    2:  // Draining
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

END_PROGRAM

