PROGRAM conveyor_seq
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    OFF := 0;
    STARTING := 1;
    RUNNING := 2;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    OFF:
        IF StopPB OR NOT EStop THEN
            State := OFF;
        ELSIF StartPB AND EStop THEN
            State := STARTING;
        END_IF;
    STARTING:
        IF StopPB OR NOT EStop THEN
            State := OFF;
        ELSIF State = STARTING AND EStop AND PT_SEQ.T#0 >= PT_SEQ THEN
            State := RUNNING;
        END_IF;
    RUNNING:
        IF StopPB OR NOT EStop THEN
            State := OFF;
        END_IF;
END_CASE;

IF State >= STARTING AND EStop THEN
    C2 := TRUE;
ELSE
    C2 := FALSE;
END_IF;

IF State >= RUNNING AND EStop THEN
    C1 := TRUE;
ELSE
    C1 := FALSE;
END_IF;

END_PROGRAM

PROGRAM conveyor_seq
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR CONSTANT
    OFF : INT := 0;
    STARTING : INT := 1;
    RUNNING : INT := 2;
END_VAR
VAR
    State : INT;
END_VAR
VAR
    T1 : TON;
END_VAR

T1(IN := TRUE, PT := T#2s);

CASE State OF
    OFF:
        C1 := FALSE;
        C2 := FALSE;
        IF StartPB AND EStop THEN
            State := STARTING;
        END_IF;
    STARTING:
        C2 := TRUE;
        IF T1.Q OR StopPB OR NOT EStop THEN
            State := OFF;
        ELSIF T1.Q THEN
            State := RUNNING;
        END_IF;
    RUNNING:
        C1 := TRUE;
        C2 := TRUE;
        IF StopPB OR NOT EStop THEN
            State := OFF;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM conveyor_seq
VAR_INPUT
    StartPB : BOOL;
    StopPB  : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    OFF := 0;
    STARTING := 1;
    RUNNING := 2;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    OFF:
        IF StopPB OR NOT EStop THEN
            State := OFF;
        ELSIF StartPB AND EStop THEN
            State := STARTING;
        END_IF;
    STARTING:
        C2 := TRUE;
        IF State >= RUNNING THEN
            State := RUNNING;
        END_IF;
    RUNNING:
        IF StopPB OR NOT EStop THEN
            State := OFF;
        ELSIF State <= STARTING THEN
            State := STARTING;
        END_IF;
END_CASE;

IF State >= RUNNING THEN
