    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0:
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1:
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF StartPB AND EStop AND State >= 1 THEN
            State := State + 1;
        END_IF;
    2:
        IF StopPB OR NOT EStop THEN
            State := 0;
        ELSIF StartPB AND EStop AND State >= 2 THEN
            State := State + 1;
        END_IF;
    3:
        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

CASE State OF
    1: C3 := TRUE;
    2: C3 := TRUE; C2 := TRUE;
    3: C3 := TRUE; C2 := TRUE; C1 := TRUE;
    DEFAULT: C3 := FALSE; C2 := FALSE; C1 := FALSE;
END_CASE;

END_PROGRAM

